    InfluxDBv2Parameters.add_member(:influxql_max_select_buckets, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Long, location_name: 'influxqlMaxSelectBuckets', traits: {"smithy.api#documentation" => "<p>Maximum number of group by time buckets a SELECT statement can create. 0 allows an unlimited number of buckets.</p>\n         <p>Default: 0</p>", "smithy.api#range" => {"min" => 0, "max" => 1000000000000}}))
